"use strict";module.exports=(n,e={})=>{const t=Number.isSafeInteger(parseInt(e.margin))?new Array(parseInt(e.margin)).fill(" ").join(""):e.margin||"",r=e.width;return(n||"").split(/\r?\n/g).map(n=>n.split(/\s+/g).reduce((n,e)=>(e.length+t.length>=r||n[n.length-1].length+e.length+1<r?n[n.length-1]+=` ${e}`:n.push(`${t}${e}`),n),[t]).join("\n")).join("\n")};